### Coeficiente de variación (CV)

El coeficiente de variación es una medida de precisión del experimento. Se calcula como:

$$
CV = \frac{\sqrt{MCE}}{\bar{y}_{..}} \times 100
$$

donde $MCE$ es la media cuadrática del error y $\bar{y}_{..}$ es la media general del experimento. El paquete `agricolae` lo reporta automáticamente en las funciones de comparaciones múltiples.

::: {.callout-tip}
### ¿Qué indica el CV?

Un CV alto indica que el error experimental es grande en relación con la media. Como referencia orientativa en experimentos agrícolas de campo:

- CV < 10%: excelente precisión.
- CV entre 10% y 20%: buena precisión, aceptable.
- CV entre 20% y 30%: precisión moderada.
- CV > 30%: baja precisión; conviene revisar el diseño o el manejo del experimento.
:::

### Demo interactiva: potencia del ANOVA y tamaño de muestra {.unnumbered}

La **potencia** es la probabilidad de rechazar $H_0$ cuando realmente es falsa (detectar diferencias reales). Ajusta los parámetros para ver cuántas repeticiones necesitas.

```{ojs}
//| echo: false
viewof k_pot    = Inputs.range([2, 6],   {step: 1,    value: 3,    label: "Número de tratamientos (k):"})
viewof r_pot    = Inputs.range([2, 20],  {step: 1,    value: 5,    label: "Repeticiones por tratamiento (r):"})
viewof delta    = Inputs.range([0.25, 5],{step: 0.25, value: 2,    label: "Diferencia mínima detectable (δ):"})
viewof sigma_p  = Inputs.range([0.25, 4],{step: 0.25, value: 1.5,  label: "Desviación estándar del error (σ):"})
viewof alpha_p  = Inputs.select([0.10, 0.05, 0.01], {label: "Nivel α:", value: 0.05,
  format: x => `α = ${x}`})
```

```{ojs}
//| echo: false
{
  // ── Función gamma logarítmica (Lanczos) ─────────────────────────────────
  function lgam(z) {
    const c = [76.18009172947146,-86.50532032941677,24.01409824083091,
               -1.231739572450155,1.208650973866179e-3,-5.395239384953e-6];
    let x = z, t = z + 5.5, s = 1.000000000190015;
    t -= (z + 0.5) * Math.log(t);
    for (let j = 0; j < 6; j++) s += c[j] / ++x;
    return -t + Math.log(2.5066282746310005 * s / z);
  }

  // ── Fracción continua de Lentz para I_x(a,b) ────────────────────────────
  function betacf(a, b, x) {
    const MAXIT = 200, EPS = 3e-7, FPMIN = 1e-30;
    const qab = a + b, qap = a + 1, qam = a - 1;
    let c = 1, d = 1 - qab * x / qap;
    if (Math.abs(d) < FPMIN) d = FPMIN;
    d = 1 / d; let h = d;
    for (let m = 1; m <= MAXIT; m++) {
      const m2 = 2 * m;
      let aa = m * (b - m) * x / ((qam + m2) * (a + m2));
      d = 1 + aa * d; if (Math.abs(d) < FPMIN) d = FPMIN;
      c = 1 + aa / c; if (Math.abs(c) < FPMIN) c = FPMIN;
      d = 1 / d; h *= d * c;
      aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2));
      d = 1 + aa * d; if (Math.abs(d) < FPMIN) d = FPMIN;
      c = 1 + aa / c; if (Math.abs(c) < FPMIN) c = FPMIN;
      d = 1 / d; const del = d * c; h *= del;
      if (Math.abs(del - 1) < EPS) break;
    }
    return h;
  }

  // ── Beta incompleta regularizada I_x(a,b) ───────────────────────────────
  function betainc(a, b, x) {
    if (x <= 0) return 0; if (x >= 1) return 1;
    const lbeta = lgam(a) + lgam(b) - lgam(a + b);
    const front = Math.exp(Math.log(x)*a + Math.log(1-x)*b - lbeta) / a;
    if (x < (a + 1) / (a + b + 2))
      return front * betacf(a, b, x);
    return 1 - Math.exp(Math.log(1-x)*b + Math.log(x)*a - lbeta) / b * betacf(b, a, 1-x);
  }

  // ── CDF de F central: P(F(d1,d2) < f) = I_x(d1/2, d2/2) ────────────────
  function cdfF(f, d1, d2) {
    if (f <= 0) return 0;
    return betainc(d1/2, d2/2, d1*f / (d1*f + d2));
  }

  // ── Cuantil de F central (bisección) ────────────────────────────────────
  function qf(p, d1, d2) {
    let lo = 0, hi = 500;
    for (let i = 0; i < 120; i++) {
      const mid = (lo + hi) / 2;
      cdfF(mid, d1, d2) < p ? lo = mid : hi = mid;
    }
    return (lo + hi) / 2;
  }

  // ── Potencia usando la serie de Poisson CORRECTA ─────────────────────────
  // P(F_nc(d1,d2,λ) > Fcrit) = 1 − Σ_j w_j · I_x(d1/2+j, d2/2)
  // con x = Fcrit·d1 / (Fcrit·d1 + d2)  ← FIJO para todos los j
  // w_j = exp(−λ/2)·(λ/2)^j / j!
  function powerANOVA(k, r, delta, sigma, alpha) {
    const d1 = k - 1, d2 = k * (r - 1);
    if (d2 <= 0) return 0.05;
    const lam     = r * delta * delta / (sigma * sigma);
    const fcrit   = qf(1 - alpha, d1, d2);
    const xFixed  = fcrit * d1 / (fcrit * d1 + d2);   // ← fijo
    const halfLam = lam / 2;
    let logW = -halfLam, cdfNC = 0;
    for (let j = 0; j < 80; j++) {
      if (j > 0) logW += Math.log(halfLam) - Math.log(j);
      const wj = Math.exp(logW);
      if (wj < 1e-14) break;
      cdfNC += wj * betainc(d1/2 + j, d2/2, xFixed);
    }
    return Math.min(0.9999, Math.max(0.0001, 1 - cdfNC));
  }

  // ── Datos de la curva ────────────────────────────────────────────────────
  const rVals = Array.from({length: 19}, (_, i) => i + 2);
  const curve = rVals.map(rv => ({r: rv, pot: powerANOVA(k_pot, rv, delta, sigma_p, alpha_p)}));
  const potAct = powerANOVA(k_pot, r_pot, delta, sigma_p, alpha_p);
  const rMin80 = rVals.find(rv => powerANOVA(k_pot, rv, delta, sigma_p, alpha_p) >= 0.80) ?? ">20";

  // ── SVG ──────────────────────────────────────────────────────────────────
  const w = 500, h = 260, mg = {t: 20, r: 60, b: 56, l: 60};
  const W = w - mg.l - mg.r, H = h - mg.t - mg.b;
  const xS = d3.scaleLinear().domain([2, 20]).range([0, W]);
  const yS = d3.scaleLinear().domain([0, 1]).range([H, 0]);

  const svg = d3.create("svg")
    .attr("viewBox", `0 0 ${w} ${h}`).attr("width","100%")
    .style("max-width",`${w}px`).style("font-family","sans-serif");
  const g = svg.append("g").attr("transform",`translate(${mg.l},${mg.t})`);

  // Banda 80 %
  g.append("line").attr("x1",0).attr("x2",W).attr("y1",yS(0.8)).attr("y2",yS(0.8))
    .attr("stroke","#bab9b4").attr("stroke-dasharray","4,3").attr("stroke-width",1);
  g.append("text").attr("x",W+4).attr("y",yS(0.8)+4).attr("font-size",10).attr("fill","#7a7974").text("80%");

  // Área rellena
  g.append("path").datum(curve)
    .attr("fill","#01696f").attr("fill-opacity",0.10)
    .attr("d", d3.area().x(d=>xS(d.r)).y0(H).y1(d=>yS(d.pot)).curve(d3.curveCatmullRom));

  // Línea de potencia
  g.append("path").datum(curve)
    .attr("fill","none").attr("stroke","#01696f").attr("stroke-width",2.5)
    .attr("d", d3.line().x(d=>xS(d.r)).y(d=>yS(d.pot)).curve(d3.curveCatmullRom));

  // Punto actual
  g.append("circle").attr("cx",xS(r_pot)).attr("cy",yS(potAct)).attr("r",7)
    .attr("fill","#01696f").attr("stroke","white").attr("stroke-width",2);
  const labelX = r_pot > 14 ? xS(r_pot) - 10 : xS(r_pot) + 10;
  const anchor = r_pot > 14 ? "end" : "start";
  g.append("text").attr("x",labelX).attr("y",yS(potAct)-8)
    .attr("text-anchor",anchor).attr("font-size",12).attr("font-weight","600")
    .attr("fill","#01696f").text(`${(potAct*100).toFixed(1)}%`);

  // Ejes
  g.append("g").attr("transform",`translate(0,${H})`).call(d3.axisBottom(xS).ticks(9))
    .selectAll("text").attr("font-size",11);
  g.append("g").call(d3.axisLeft(yS).ticks(5).tickFormat(d3.format(".0%")))
    .selectAll("text").attr("font-size",11);

  // Etiquetas
  g.append("text").attr("x",W/2).attr("y",H+36).attr("text-anchor","middle")
    .attr("font-size",12).attr("fill","#28251d").text("Repeticiones por tratamiento (r)");
  g.append("text").attr("transform","rotate(-90)").attr("x",-H/2).attr("y",-46)
    .attr("text-anchor","middle").attr("font-size",12).attr("fill","#28251d").text("Potencia (1 − β)");

  // r mínimo para 80%
  g.append("text").attr("x",W/2).attr("y",H+50).attr("text-anchor","middle")
    .attr("font-size",11).attr("fill","#964219")
    .text(`r mínimo para potencia ≥ 80 %: ${rMin80} repeticiones`);

  return svg.node();
}
```

::: {.callout-tip}
**Regla práctica:** en experimentación agrícola se recomienda una potencia mínima del **80 %** (línea punteada). Si la potencia actual es baja, aumenta el número de repeticiones o mejora el control ambiental del experimento (por ejemplo, usando DBCA en lugar de DCA para reducir σ).
:::


