factorA <- c("Cero", "Convencional")
factorB <- c("V1", "V2", "V3")
dpd <- design.split(
  trt1 = factorA,
  trt2 = factorB,
  r = 3,
  seed = 333,
  serie = 2,
  design = "rcbd"
)
dpd$book
