  Labranza = c("Cero", "Convencional"),
  Variedad = c("V1", "V2", "V3")
)
datos_dpd$Rendimiento <- c(
  rnorm(3, 4.0, 0.25), rnorm(3, 4.5, 0.25), rnorm(3, 4.2, 0.25),
  rnorm(3, 4.8, 0.25), rnorm(3, 6.3, 0.25), rnorm(3, 4.9, 0.25)
)
with(datos_dpd,
